'gruaud-larose|2007':{v:'Weighing of the crop. Plot selection in the tank',src:'chateau-gruaud-larose-2007-ang.pdf',label:'VINIFICATION ',lang:'en'},
'gruaud-larose|2019':{v:'Stéphanie Lebaron-Bouchonneau|',src:'chateau-gruaud-larose-2019-fr.pdf',label:'chai : ',lang:'fr'},
'gruaud-larose|2022':{v:'The vineyard is managed by using respectful Agronomic methods of the environment. Its production has been certified as an organic farming since August 2022 and the main Biodynamic principles have been implemented. We restore our land by focusing on living and its environment: Edges and forest are replanted and redraw the borders of our plots. During winter, inter-row vegetation are grazed by a flock of 300 sheeps. From spring to the harvest, only light ploughing labour is applied between the rows to keep the land clean. Regaining balance in our ecosystem is one of the keys to help the terroir express itself.',src:'Chateau-Gruaud-Larose-2022-ang.pdf',label:'VINIFICATION ',lang:'en'},
'gruaud-larose|2023':{v:'Yeast addition | Fermentation',src:'Chateau-Gruaud-Larose-2023-ang.pdf',label:'VINIFICATION ',lang:'fr'},
'gruaud-larose|2024':{v:'Selection by hands and optical sorting table Plot and micro-plot selection thanks to small vats (55 hl to 130 hl) 100% wood (thermo-regulated vats) Yeast addition | Fermentation',src:'Chateau-Gruaud-Larose-2024-ang.pdf',label:'VINIFICATION ',lang:'en'},
