'haut-bages-liberal|2018':{v:'Traditionnelle, en cuve béton.',src:'Haut-Bages-Liberal-2018-FT-FR-1.pdf',label:'Vinification ',lang:'fr'},
'haut-bages-liberal|2021':{v:'Vinification parcellaire. Macération avec apport d’un gaz neutre pour stimuler des mouvements en douceur. Remontage d’un volume/jour. Pressurage vertical. Inertage à l’azote pendant les transferts afin de protéger les mouts de l’oxydation. Absence d’ajout de S02.',src:'Fiche_Technique_CERES_de_Haut-Bages_Liberal_HTM_RO_2021_Francais.pdf',label:'VINIFICATION ',lang:'fr'},
'haut-bages-liberal|2023':{v:'Vinification parcellaire. 24 jours de macération à 20-24°C, avec apport d’un gaz neutre qui stimule des mouvements, pour une extraction douce et régulière. Pas de remontage. Pressurage vertical pour apporter un soin particulier aux presses.',src:'Haut-Bages-Liberal-2023-FT-FR.pdf',label:'VINIFICATION ',lang:'fr'},
'haut-bages-liberal|2025':{v:'Vinification parcellaire. 23 jours de macération entre 18°C et 24°C avec apport d’un gaz neutre qui stimule les mouvements, pour une extraction douce et régulière. Pressurage vertical pour apporter un soin particulier aux presses. LES PRATIQUES CULTURALES Wine from organic grapes. Issu de raisins Demeter. Agroécologie & Agroforesterie.',src:'FT_Chateau_Haut_Bages_Liberal_PAU_RO_2025_Francais.pdf',label:'VINIFICATION ',lang:'fr'},
'haut-bailly|2010':{v:'gentle extraction with a controlled fermentation',src:'2010__en-vintage-2010-excellence-2.txt',label:'winemaking: ',lang:'en'},
'haut-bailly|2024':{v:'Le mois de septembre est à nouveau marqué par des épisodes pluvieux intenses. Les vendanges débutent le 18 septembre et se terminent le 4 octobre.',src:'2024__millesime-2024.txt',label:'Vinifications: ',lang:'fr'},
'haut-batailley|2011':{v:'Maceration (average 3 weeks)',src:'Haut-Batailley-2011-FT-GB-93.pdf',label:'Vinification: ',lang:'fr'},
'issan|2014':{v:'“ Haute-Couture ” Les fermentations se déroulent traditionnellement avec des remontages très doux pour respecter la matière et la vivacité des raisins.',src:'CHATEAU_ISSAN_2014.pdf',label:'Vinifications ',lang:'fr'},
'kirwan|2023':{v:'EASIER With such ripeness levels, the vinifications were straightforward and required minimum winemaker intervention. Pump-overs were unnecessary; our R’pulse system was largely sufficient to carry out the extraction process. The 2023 wine batches were placed in barrels very early, in mid-October 2023, and were blended at the first racking at the end of January 2024.',src:'2023-FACT-SHEET-ENG-ChateauKirwan.pdf',label:'VINIFICATION ',lang:'en'},
'la-conseillante|2002':{v:'Pre-fermentation cold-maceration for 2 to 5 days, in tank for 14 to 28 days La Conseillante 2002 is a very elegant wine, marked by notes of violet, blueberry and truffle.',src:'Technical-data-La-Conseillante-2002.pdf',label:'Winemaking : ',lang:'en'},
'la-conseillante|2009':{v:'Pre-fermentation cold-maceration for 3 to 5 days, in tank for 3 to 4 weeks La Conseillante 2009 stands out for having been exceptionally fine tasting from the very outset.',src:'Technical-data-La-Conseillante-2009.pdf',label:'Winemaking : ',lang:'en'},
'la-conseillante|2010':{v:'Pre-fermentation cold-maceration for 3 to 5 days, in tank for 3 to 4 weeks 2010 closes a superb trilogy of vintages that started with 2008 and is reminiscent of 1988-1989- 1990. It delights the purists with its vigour and superb balance and its perfect Bordeaux style. It is denser than the 2009 and has distinctly more acidity, which will make it longer keeping. In this way, it is more like the 1989.',src:'Technical-data-La-Conseillante-2010.pdf',label:'Winemaking : ',lang:'en'},
'la-conseillante|2011':{v:'Acier inoxydable, entièrement thermo régulé',src:'Fiche-technique-La-Conseillante-2011.pdf',label:'Cuvier: ',lang:'fr'},
'la-conseillante|2012':{v:'22 cuves béton revêtues epoxy, entièrement thermorégulées',src:'Fiche-technique-La-Conseillante-2012.pdf',label:'Cuvier: ',lang:'fr'},
'la-conseillante|2013':{v:'Pre-fermentation cold-maceration for 2 to 5 days, in tank for 3 to 4 weeks Smooth, the wine develops raspberry notes.',src:'Technical-data-La-Conseillante-2013.pdf',label:'Winemaking : ',lang:'en'},
'la-conseillante|2014':{v:'Pre-fermentary cold-maceration for 3 days, vatted for 29 days Elegant in the mouth with a precise structure, this vintage is faithful to La Conseillante philoso- phy.',src:'Technical-data-La-Conseillante-2014.pdf',label:'Winemaking : ',lang:'en'},
'la-conseillante|2015':{v:'Macération pré fermentaire à froid de 5 jours, cuvaison de 4 semaines 2015 est un millésime exceptionnel.',src:'Fiche-technique-La-Conseillante-2015.pdf',label:'Vinification: ',lang:'fr'},
'la-conseillante|2016':{v:'22 cuves béton revêtues epoxy, entièrement thermorégulées',src:'Fiche-technique-La-Conseillante-2016.pdf',label:'Cuvier: ',lang:'fr'},
