'la-conseillante|2019':{v:'Macération pré fermentaire à froid de 4 jours, cuvaison de 27 jours 5% de la production en vinification intégrale Jamais l’',src:'Fiche-technique-La-Conseillante-2019.pdf',label:'Vinification: ',lang:'fr'},
