'la-mondotte|2014':{v:'en cuves de bois thermorégulées de 20 à 30 jours selon les millésimes Extraction par pigeage pneumatique Fermentation malolactique',src:'Mondotte-2014-FT-FR-872.pdf',label:'Vinification : ',lang:'fr'},
'la-tour-carnet|2011':{v:'vendanges manuelles en petites cagettes avec premier tri',src:'Tour-Carnet-2011-FT-FR-168.pdf',label:'Vinification : ',lang:'fr'},
'la-tour-carnet|2019':{v:'Primary sorting on the vine - Manual sorting on a vibrating table before and after destemming, using a Pellenc WINERY - Each grape sorted by density - The grapes are cooled in a cryogenic tunnel (by spraying liquid nitrogen) - Gravity-fed into tanks through a wide tank funnel - Small cement and wooden tanks - Cold pre-ferment maceration (8°C) - Fully manual crushing - Low',src:'FT-Chateau-La-Tour-Carnet-rouge-2019-EN.pdf',label:'In the winery: ',lang:'en'},
'la-tour-carnet|2025':{v:'elles sont réalisées directement en barriques, dès le premier pressurage. Cette méthode ancestrale, rare et exigeante, permet d’obtenir des vins liquoreux d’une complexité aromatique incomparable, véritable signature du Sauternais. « Le secret du Clos Haut-Peyraguey réside dans la date des vendanges et du ramassage des raisins à pleine maturité. En effet, le tri est un moment clé pour obtenir un vin de qualité, qui est déterminé par une sélection des baies les plus gourmandes et savoureuses. La vendange est pressée durant toute une nuit pour une extraction douce, en respectant cette noble matière première.',src:'2025__vins-vendanges-2025.txt',label:'fermentations ',lang:'fr'},
'la-violette|2025':{v:'Macération pré-fermentaire à froid. Cuvaison 20 à 30 jours selon les lots.',src:'la-violette-2025-cc00f818.pdf',label:'VINIFICATION ',lang:'fr'},
'lafaurie-peyraguey|2022':{v:'FERMENTATION PERIOD 25 à 30 jours en fûts de chêne français de 225 litres 25 to 30 days in french oak barrels of 225 liters',src:'VSD_2022-_Ch._Lafaurie-Peyraguey_sauternes.pdf',label:'FERMENTATION — ',lang:'fr'},
'lafaurie-peyraguey|2023':{v:'FERMENTATION PERIOD 20 jours en fûts de chêne français de 225 litres 20 days in french oak barrels of 225 liters',src:'Fiche_Technique_Chateau_LAFAURIE-PEYRAGUEY_SAU_BL_2023_Francais_et_Anglais.pdf',label:'FERMENTATION — ',lang:'fr'},
'lafaurie-peyraguey|2024':{v:'20 jours en fûts de chêne français de 225 litres',src:'ft_chateau-lafaurie-peyraguey-2024_fiche-technique-chateau-lafaurie-peyraguey-sau-bl.pdf',label:'FERMENTATION ',lang:'fr'},
